for suffix,report in [('jp0473669',tin),('ja048427j',mn)]:
    d=B/suffix;intake=load(d/'intake-manifest.json');snapshot=load(d/'ledger-candidate-snapshot.json')
    docs=[]
    for item in intake['documents']:
        item={**item,'verified_role':'supporting_information'if '_si_'in Path(item['path']).name else'main_article','hash_stable_after_screening':sha(Path(item['path']))==item['sha256']}
        assert item['hash_stable_after_screening']
        item['role_basis']='Actual title/byline and article content'if item['verified_role']=='main_article'else'Supporting title page, authors, internal manuscript code and matched source figures'
        docs.append(item)
    report['documents']=docs
    report['intake_manifest_sha256']=sha(d/'intake-manifest.json')
    report['local_candidate_check']={'ledger_snapshot_path':str(d/'ledger-candidate-snapshot.json'),'snapshot_sha256':sha(d/'ledger-candidate-snapshot.json'),'ledger_sha256_at_intake':intake['ledger_sha256_at_read'],'group_ids':list(snapshot['groups']),'file_keys':list(snapshot['files']),'current_ledger_not_mutated':True,'incoming_legacy_duplicate_groups_are_not_additional_papers':True}
    (d/'screening.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
    lines=[report['title'],'',f"DOI: {report['doi']}",f"Authors: {'; '.join(report['authors'])}",f"{report['journal']} {report['year']}, {report['volume']}, {report['printed_pages']}",'',f"Decision: RETAIN. Recipe present: {report['recipe_present']}.",report['recipe_relevance_rationale'],'','Screening scope',report['scope'],'','Actual coverage',json.dumps(report['reading_coverage'],ensure_ascii=False,indent=2),'','Document identity and pairing']
    for e in report['identity_evidence']:lines.append('- '+e['locator']+': '+e['observation'])
    for doc in docs:lines.append(f"- {doc['location']} / {doc['verified_role']}: {doc['path']} | {doc['page_count']} pages | SHA256 {doc['sha256']} | PDF magic {doc['pdf_signature']} | EOF marker {doc['has_eof_marker']} | unchanged after reading {doc['hash_stable_after_screening']}")
    lines+=['','Recipe outlines; not final recipe counts']
    for route in report['recipe_outline']:
        lines+=['',route['outline_id']+' ('+route['kind']+')','Locators: '+'; '.join(route['locators'])]+['- '+x for x in route['steps']]
        if route.get('missing_details'):lines+=['Missing: '+'; '.join(route['missing_details'])]
        if route.get('scope_note'):lines+=[route['scope_note']]
    lines+=['','SI status',json.dumps(report['si_status'],ensure_ascii=False,indent=2),'','Source cautions']+['- '+x for x in report['source_cautions']]+['','Next actions']+['- '+x for x in report['next_actions']]
    (d/'screening-notes.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
    print(json.dumps({'suffix':suffix,'recipe_present':report['recipe_present'],'screening_sha256':sha(d/'screening.json'),'notes_sha256':sha(d/'screening-notes.md'),'documents':len(docs)}))
